import{_ as t,c as a,o as s,a2 as i}from"./chunks/framework.DkPtUiZm.js";const m=JSON.parse('{"title":"Confidentialité — SIA UI Demo","description":"","frontmatter":{},"headers":[],"relativePath":"legal/confidentialite-demo-mobile.md","filePath":"legal/confidentialite-demo-mobile.md","lastUpdated":1795438092000}'),n={name:"legal/confidentialite-demo-mobile.md"};function o(r,e,l,p,c,d){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="confidentialite-—-sia-ui-demo" tabindex="-1">Confidentialité — SIA UI Demo <a class="header-anchor" href="#confidentialite-—-sia-ui-demo" aria-label="Permalink to &quot;Confidentialité — SIA UI Demo&quot;">​</a></h1><p>Dernière mise à jour : <strong>23 novembre 2026</strong>.</p><h2 id="editeur-et-perimetre" tabindex="-1">Éditeur et périmètre <a class="header-anchor" href="#editeur-et-perimetre" aria-label="Permalink to &quot;Éditeur et périmètre&quot;">​</a></h2><p>Cette politique concerne l’application Android <strong>SIA UI Demo</strong>, éditée par le projet SIA UI. Elle décrit la version de démonstration préparée dans ce dépôt. Pour contacter le projet : <a href="https://github.com/BeatJo/sia-ui/issues" target="_blank" rel="noreferrer">BeatJo/sia-ui, rubrique Issues</a>. Un compte GitHub peut être nécessaire ; ne publiez aucune donnée sensible.</p><h2 id="une-demonstration-locale" tabindex="-1">Une démonstration locale <a class="header-anchor" href="#une-demonstration-locale" aria-label="Permalink to &quot;Une démonstration locale&quot;">​</a></h2><p>L’application présente des composants et des parcours d’exemple. La session Membre ou Administrateur est une simulation locale : aucun compte distant, mot de passe ou jeton de connexion n’est créé. Elle ne se connecte à aucun service métier.</p><h2 id="donnees-sur-l-appareil" tabindex="-1">Données sur l’appareil <a class="header-anchor" href="#donnees-sur-l-appareil" aria-label="Permalink to &quot;Données sur l’appareil&quot;">​</a></h2><p>Le nom de démonstration, le rôle, les préférences et les contacts d’exemple peuvent être conservés dans le stockage privé de l’application. Les autres saisies servent aux exemples. Utilisez des données fictives. L’application n’envoie pas ces données vers un serveur du projet SIA UI.</p><h2 id="mises-a-jour-de-l-application" tabindex="-1">Mises à jour de l’application <a class="header-anchor" href="#mises-a-jour-de-l-application" aria-label="Permalink to &quot;Mises à jour de l’application&quot;">​</a></h2><p>Les versions compatibles avec EAS Update contactent le service d’Expo pour vérifier et télécharger les mises à jour. Expo reçoit les informations techniques de la requête, dont l’adresse IP, la plateforme et la version de compatibilité. Les saisies, contacts de démonstration et fichiers locaux ne sont pas transmis pour cette vérification.</p><h2 id="photos-documents-et-camera" tabindex="-1">Photos, documents et caméra <a class="header-anchor" href="#photos-documents-et-camera" aria-label="Permalink to &quot;Photos, documents et caméra&quot;">​</a></h2><p>La sélection de fichiers et d’images utilise le sélecteur système. La caméra est demandée uniquement si vous choisissez de prendre une photo. Les fichiers et leurs aperçus restent locaux ; certaines sélections créent une copie temporaire dans le cache. Aucun envoi automatique n’est effectué. Le microphone n’est pas utilisé. L’application ne lit pas le carnet de contacts de l’appareil : les « Contacts » présentés sont des exemples internes.</p><h2 id="presse-papiers-partage-et-liens-externes" tabindex="-1">Presse-papiers, partage et liens externes <a class="header-anchor" href="#presse-papiers-partage-et-liens-externes" aria-label="Permalink to &quot;Presse-papiers, partage et liens externes&quot;">​</a></h2><p>Une commande Copier écrit le contenu choisi dans le presse-papiers. Partager ouvre la feuille système : les données sont transmises uniquement au destinataire ou au service que vous choisissez. Les liens externes sont ouverts à votre demande. Les services externes, notamment GitHub pour le contact, appliquent leurs propres politiques de confidentialité.</p><h2 id="conservation-et-suppression" tabindex="-1">Conservation et suppression <a class="header-anchor" href="#conservation-et-suppression" aria-label="Permalink to &quot;Conservation et suppression&quot;">​</a></h2><p>La déconnexion efface la session locale, mais pas les préférences ni les contacts. Pour supprimer toutes les données locales, ouvrez <strong>Paramètres Android → Applications → SIA UI Demo → Stockage → Effacer les données</strong>. Les noms des menus peuvent varier. La désinstallation supprime aussi le stockage privé de l’application. Aucun compte distant n’est à supprimer. Les fichiers partagés vers d’autres applications ne sont pas effacés par cette action.</p><p>La sauvegarde Android automatique des données de cette démo est désactivée dans la configuration de l’application.</p><h2 id="publicite-et-mesure-d-audience" tabindex="-1">Publicité et mesure d’audience <a class="header-anchor" href="#publicite-et-mesure-d-audience" aria-label="Permalink to &quot;Publicité et mesure d’audience&quot;">​</a></h2><p>Cette version ne comporte ni publicité ni outil de mesure d’audience configuré par le projet. Les services Android, Google Play et les applications externes restent soumis à leurs propres politiques. Cette politique sera revue si des services sont ajoutés à l’application.</p>',19)])])}const h=t(n,[["render",o]]);export{m as __pageData,h as default};
